<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;
Auth::requirePermission('competitors.view');$pdo=Database::connection();
function wdcpLower(string $v):string{return function_exists('mb_strtolower')?mb_strtolower($v,'UTF-8'):strtolower($v);}function wdcpLabel(string $v):string{return ucwords(str_replace(['_','-',':'],' ',trim($v)));}function wdcpUrl(array $c=[]):string{$q=array_merge($_GET,$c);foreach($q as $k=>$v)if($v===''||$v===null)unset($q[$k]);return'?'.http_build_query($q);}
$q=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$style=(string)($_GET['style']??'');$complete=(string)($_GET['complete']??'');$sort=(string)($_GET['sort']??'name');$order=strtolower((string)($_GET['order']??'asc'))==='desc'?'desc':'asc';
$sql="SELECT w.id,w.identity_code,w.entry_type,w.display_name,w.country,w.solo_competitor_id,w.photo_url,c.photo_url shared_photo,COUNT(r.id) registration_count,GROUP_CONCAT(CONCAT(r.event_key,':',r.category_key) ORDER BY r.event_key,r.category_key SEPARATOR ',') registrations FROM bdc_wdc_identities w LEFT JOIN bdc_competitors c ON c.id=w.solo_competitor_id LEFT JOIN bdc_wdc_registrations r ON r.wdc_identity_id=w.id AND r.status='registered' WHERE w.status='active' GROUP BY w.id,w.identity_code,w.entry_type,w.display_name,w.country,w.solo_competitor_id,w.photo_url,c.photo_url ORDER BY LOWER(w.display_name),w.id LIMIT 500";
$all=$pdo->query($sql)->fetchAll();$names=[];foreach($all as $r){$k=$r['entry_type'].'|'.wdcpLower(trim((string)$r['display_name']));$names[$k]=($names[$k]??0)+1;}foreach($all as &$r){$r['photo_display']=$r['photo_url']?:$r['shared_photo'];$r['registration_list']=array_values(array_filter(explode(',',(string)$r['registrations'])));$r['search']=wdcpLower(implode(' ',[$r['display_name'],$r['identity_code'],$r['country'],$r['registrations']]));$r['dance_style']=str_contains($r['search'],'salsa')?'salsa':(str_contains($r['search'],'bachata')?'bachata':'');$k=$r['entry_type'].'|'.wdcpLower(trim((string)$r['display_name']));$r['duplicate_count']=max(0,($names[$k]??1)-1);$r['completeness']=(trim((string)$r['photo_display'])!==''?1:0)+(trim((string)$r['country'])!==''?1:0)+((int)$r['registration_count']>0?1:0);}unset($r);
$summary=['WDC identities'=>count($all),'Category entries'=>array_sum(array_map(static fn(array $r):int=>(int)$r['registration_count'],$all)),'Shared people'=>count(array_filter($all,static fn(array $r):bool=>(int)$r['solo_competitor_id']>0)),'Missing photos'=>count(array_filter($all,static fn(array $r):bool=>trim((string)$r['photo_display'])==='')),'Missing country'=>count(array_filter($all,static fn(array $r):bool=>trim((string)$r['country'])==='')),'Possible duplicates'=>count(array_filter($all,static fn(array $r):bool=>(int)$r['duplicate_count']>0))];
$rows=array_values(array_filter($all,static function(array $r)use($q,$type,$style,$complete):bool{if($q!==''&&!str_contains($r['search'],wdcpLower($q)))return false;if($type!==''&&$r['entry_type']!==$type)return false;if($style!==''&&$r['dance_style']!==$style)return false;if($complete==='missing_photo'&&trim((string)$r['photo_display'])!=='')return false;if($complete==='missing_country'&&trim((string)$r['country'])!=='')return false;if($complete==='no_registration'&&(int)$r['registration_count']>0)return false;if($complete==='duplicate'&&(int)$r['duplicate_count']===0)return false;return true;}));
$sorters=['name'=>static fn(array $r):string=>wdcpLower((string)$r['display_name']),'wdc_id'=>static fn(array $r):string=>(string)$r['identity_code'],'country'=>static fn(array $r):string=>wdcpLower((string)$r['country']),'type'=>static fn(array $r):string=>(string)$r['entry_type'],'entries'=>static fn(array $r):int=>(int)$r['registration_count'],'completeness'=>static fn(array $r):int=>(int)$r['completeness']];$sort=array_key_exists($sort,$sorters)?$sort:'name';usort($rows,static function(array $a,array $b)use($sorters,$sort,$order):int{$n=$sorters[$sort]($a)<=>$sorters[$sort]($b);return$order==='desc'?-$n:$n;});
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="wdc-premium-'.date('Y-m-d-His').'.csv"');$out=fopen('php://output','wb');fputcsv($out,['WDC ID','Participant','Entry Type','Country','Style','Registrations','Photo','Duplicate']);foreach($rows as $r)fputcsv($out,[$r['identity_code'],$r['display_name'],$r['entry_type'],$r['country'],$r['dance_style'],implode(' | ',$r['registration_list']),$r['photo_display']?'Yes':'No',$r['duplicate_count']?'Yes':'No']);fclose($out);exit;}$sortLink=static fn(string $c):string=>wdcpUrl(['sort'=>$c,'order'=>$sort===$c&&$order==='asc'?'desc':'asc']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Competitors</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"><style>:root{--ink:#111c33;--blue:#1967ff}body{background:linear-gradient(135deg,#edf3fb,#f8f9fc 52%,#f3edf7);color:var(--ink)}.hero{background:linear-gradient(120deg,#0d1b36,#172c54 65%,#511933);color:#fff;border-radius:22px;padding:24px;box-shadow:0 18px 48px #2032542e}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:14px}.metric,.panel{border:1px solid #ffffffaa;background:#ffffffef;box-shadow:0 14px 36px #20325414}.metric{border-radius:18px}.panel{border-radius:20px}.photo{width:64px;height:76px;object-fit:cover;border-radius:14px}.identity{color:#df2270;font-weight:700}.tag{border-radius:999px;padding:.2rem .55rem;font-size:.72rem;font-weight:700;background:#e8f1ff;color:#075ad6}.registration{border-left:3px solid var(--blue);padding-left:.55rem;margin:.35rem 0;min-width:235px}.sortable{color:inherit;text-decoration:none}.actions{display:flex;gap:.35rem;flex-wrap:wrap}.progress{height:6px}</style></head><body><main class="container-fluid py-4" style="max-width:1720px"><section class="hero mb-4"><div class="d-flex justify-content-between gap-3 flex-wrap"><div><div class="small text-info fw-bold mb-2">WDC COMPETITOR MANAGEMENT</div><h1 class="h2 mb-1">Dance Cup Competitors</h1><p class="mb-0 text-white-50">Complete WDC identity and registration workspace.</p></div><div><a class="btn btn-light" href="competitor-edit.php">Add competitor</a></div></div></section><section class="summary mb-4"><?php foreach($summary as $label=>$value):$target=$label==='Missing photos'?wdcpUrl(['complete'=>'missing_photo']):($label==='Missing country'?wdcpUrl(['complete'=>'missing_country']):($label==='Possible duplicates'?wdcpUrl(['complete'=>'duplicate']):'#'));?><a href="<?=e($target)?>" class="metric text-decoration-none text-dark p-3"><div class="small text-muted"><?=e($label)?></div><div class="display-6 fw-bold"><?=$value?></div></a><?php endforeach;?></section>
<form class="panel p-3 mb-3"><div class="row g-2"><div class="col-xl-5"><label class="form-label small fw-bold">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Name, WDC ID, country or category"></div><?php foreach(['type'=>['Entry type',[''=>'All types','solo'=>'Solo','couple'=>'Couple','duo'=>'Duo','pro_am'=>'Pro Am','team'=>'Team']],'style'=>['Dance style',[''=>'All styles','bachata'=>'Bachata','salsa'=>'Salsa']],'complete'=>['Profile check',[''=>'All profiles','missing_photo'=>'Missing photo','missing_country'=>'Missing country','no_registration'=>'No registration','duplicate'=>'Possible duplicate']]] as $field=>[$label,$options]):?><div class="col-md"><label class="form-label small fw-bold"><?=e($label)?></label><select class="form-select" name="<?=$field?>"><?php foreach($options as $value=>$text):?><option value="<?=e($value)?>" <?=($$field===$value)?'selected':''?>><?=e($text)?></option><?php endforeach;?></select></div><?php endforeach;?><div class="col-12 d-flex gap-2 mt-3"><button class="btn btn-dark">Apply filters</button><a class="btn btn-outline-secondary" href="competitors.php">Reset</a><a class="btn btn-outline-success ms-auto" href="<?=e(wdcpUrl(['export'=>'csv']))?>">Export CSV</a></div></div></form>
<section class="panel overflow-hidden"><div class="p-3 border-bottom d-flex justify-content-between"><strong><?=count($rows)?> competitors shown</strong><span class="text-muted small">Click a heading to sort</span></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Photo</th><?php foreach(['wdc_id'=>'WDC ID','name'=>'Participant','country'=>'Country','type'=>'Entry type','entries'=>'Registrations','completeness'=>'Profile'] as $column=>$label):?><th><a class="sortable" href="<?=e($sortLink($column))?>"><?=e($label)?></a></th><?php endforeach;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><img class="photo" src="<?=e($r['photo_display']?:url('public/assets/img/default-competitor.svg'))?>" alt=""></td><td><span class="identity"><?=e($r['identity_code'])?></span><?php if($r['duplicate_count']):?><span class="badge text-bg-warning d-block mt-1">Possible duplicate</span><?php endif;?></td><td><strong><?=e($r['display_name'])?></strong><small class="d-block text-muted"><?=e(wdcpLabel($r['dance_style']?:'Style pending'))?></small></td><td><?=e($r['country']?:'Missing')?></td><td><span class="tag"><?=e(wdcpLabel($r['entry_type']))?></span></td><td><?php foreach($r['registration_list'] as $reg):?><div class="registration"><?=e(wdcpLabel($reg))?></div><?php endforeach;?><?php if(!$r['registration_list']):?><span class="text-muted">No active registration</span><?php endif;?></td><td><div class="small mb-1"><?=$r['completeness']?> of 3 complete</div><div class="progress"><div class="progress-bar <?=$r['completeness']===3?'bg-success':'bg-warning'?>" style="width:<?=round($r['completeness']/3*100)?>%"></div></div></td><td><div class="actions"><a class="btn btn-sm btn-dark" href="competitor-edit.php?id=<?=(int)$r['id']?>">Edit profile</a><a class="btn btn-sm btn-outline-primary" href="photo-adjust.php?id=<?=(int)$r['id']?>">Adjust photo</a></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-muted py-5">No WDC competitors match these filters.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
